// Each policy keeps one independent state per key.

export class TokenBucket {
  constructor(name, capacity, refill, per) {
    this.name = name
    this.capacity = capacity // BigInt
    this.refill = refill // BigInt
    this.per = per // BigInt
    this.capacityNum = capacity * per // numerator when full
    this.states = new Map() // key -> { lastTick, numerator }
  }

  advance(key, tick) {
    let state = this.states.get(key)
    if (state === undefined) {
      state = { lastTick: tick, numerator: this.capacityNum }
      this.states.set(key, state)
      return
    }
    if (tick > state.lastTick) {
      const elapsed = tick - state.lastTick
      let numerator = state.numerator + this.refill * elapsed
      if (numerator > this.capacityNum) numerator = this.capacityNum
      state.numerator = numerator
      state.lastTick = tick
    }
  }

  allow(key) {
    const state = this.states.get(key)
    return state.numerator >= this.per
  }

  record(key) {
    const state = this.states.get(key)
    state.numerator -= this.per
  }
}

export class SlidingWindow {
  constructor(name, limit, span) {
    this.name = name
    this.limit = limit // BigInt
    this.span = span // BigInt
    this.states = new Map() // key -> array of ticks (BigInt), ascending
  }

  advance(key, tick) {
    let state = this.states.get(key)
    if (state === undefined) {
      state = []
      this.states.set(key, state)
    }
    const threshold = tick - this.span
    let cut = 0
    while (cut < state.length && state[cut] <= threshold) cut++
    if (cut > 0) state.splice(0, cut)
  }

  allow(key) {
    const state = this.states.get(key)
    return BigInt(state.length) < this.limit
  }

  record(key, tick) {
    const state = this.states.get(key)
    state.push(tick)
  }
}
"}

