 *   { policies: Map<name, policy>, routes: [{ prefix, policyNames }], events: [{ tick, key }] }
 * Throws ParseError on the first problem, per the spec's line-by-line reasons.
 */
export function parseLimiterFile(text) {
  const rawLines = text.split('\n')
  if (rawLines.length > 0 && rawLines[rawLines.length - 1] === '') rawLines.pop()

  const policies = new Map()
  const routes = []
  const routePrefixes = new Set()
  const events = []

  let eventsStarted = false
  let lastTick = null

  for (let i = 0; i < rawLines.length; i++) {
    const lineNo = i + 1
    const trimmed = rawLines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const directive = words[0]

