      throw new ParseError(lineNo, 'declarations must come before the first event')
    }

    if (directive === 'bucket') {
      if (words.length !== 5) {
        throw new ParseError(lineNo, 'expected bucket <name> <capacity> <refill> <per>')
      }
      const [, name, capacityStr, refillStr, perStr] = words
      if (!TOKEN_RE.test(name)) throw new ParseError(lineNo, `invalid policy name ${name}`)
      const capacity = parseInt_(capacityStr, 1n, 'capacity', lineNo)
      const refill = parseInt_(refillStr, 0n, 'refill', lineNo)
      const per = parseInt_(perStr, 1n, 'per', lineNo)
      if (policies.has(name)) throw new ParseError(lineNo, `policy ${name} is declared twice`)
      policies.set(name, new TokenBucket(name, capacity, refill, per))
    } else if (directive === 'window') {
      if (words.length !== 4) {
        throw new ParseError(lineNo, 'expected window <name> <limit> <span>')
      }
      const [, name, limitStr, spanStr] = words
      if (!TOKEN_RE.test(name)) throw new ParseError(lineNo, `invalid policy name ${name}`)
      const limit = parseInt_(limitStr, 0n, 'limit', lineNo)
      const span = parseInt_(spanStr, 1n, 'span', lineNo)
      if (policies.has(name)) throw new ParseError(lineNo, `policy ${name} is declared twice`)
      policies.set(name, new SlidingWindow(name, limit, span))
    } else if (directive === 'route') {
      if (words.length < 3) {
        throw new ParseError(lineNo, 'expected route <prefix> <policy>...')
      }
      const prefix = words[1]
      const policyNames = words.slice(2)
      if (!TOKEN_RE.test(prefix)) throw new ParseError(lineNo, `invalid route prefix ${prefix}`)
      if (routePrefixes.has(prefix)) throw new ParseError(lineNo, `prefix ${prefix} is routed twice`)
      for (const name of policyNames) {
        if (!policies.has(name)) throw new ParseError(lineNo, `unknown policy ${name}`)
