/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */

import { readFileSync } from 'node:fs'
import { parseLimiterFile } from './parser.js'
import { simulate } from './engine.js'
import { ParseError } from './parseError.js'

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'replay' && mode !== 'summary')) {
    process.stderr.write('error: usage: cli.js replay|summary\n')
    process.exit(2)
  }

  let input
  try {
    input = readFileSync(0, 'utf8')
  } catch {
    input = ''
  }

  let parsed
  try {
    parsed = parseLimiterFile(input)
  } catch (err) {
    if (err instanceof ParseError) {
      process.stderr.write(`error: ${err.message}\n`)
      process.exit(2)
    }
    throw err
  }

  const verdicts = simulate(parsed)

  let output
  if (mode === 'replay') {
    output = verdicts
      .map((v) => (v.allowed ? `${v.tick} ${v.key} allow` : `${v.tick} ${v.key} deny ${v.denyPolicy}`))
      .join('\n')
    if (verdicts.length > 0) output += '\n'
  } else {
    const totals = new Map() // key -> { allowed, denied }
    let totalAllowed = 0n
    let totalDenied = 0n
    for (const v of verdicts) {
      let t = totals.get(v.key)
      if (t === undefined) {
        t = { allowed: 0n, denied: 0n }
        totals.set(v.key, t)
      }
      if (v.allowed) {
        t.allowed += 1n
        totalAllowed += 1n
      } else {
        t.denied += 1n
        totalDenied += 1n
      }
    }
    const keys = [...totals.keys()].sort()
    const lines = keys.map((key) => {
      const t = totals.get(key)
      return `${key} allowed=${t.allowed} denied=${t.denied}`
    })
    lines.push(`total allowed=${totalAllowed} denied=${totalDenied}`)
    output = lines.join('\n') + '\n'
  }

  process.stdout.write(output)
  process.exit(0)
}

main()
"}

